/* ========================================
   Volta Studio — Shared Styles
   ======================================== */

@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;0,800;1,400;1,500;1,600&family=Inter:wght@300;400;500;600&display=swap');

/* Reset */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --text-light: #6B6560;
  --accent-terracotta: #C4704B;
  --accent-sage: #8B9E82;
  --accent-sand: #D4B896;
  --accent-muted: #B8A99A;
  --serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
  --max-width: 1200px;
  --reading-width: 680px;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--sans);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

/* ========================================
   Navigation
   ======================================== */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 48px;
  background: var(--bg);
  transition: background 0.3s ease;
}

.nav-logo {
  font-family: var(--serif);
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.nav-links {
  display: flex;
  gap: 40px;
  list-style: none;
}

.nav-links a {
  font-size: 0.85rem;
  font-weight: 400;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  position: relative;
  padding-bottom: 2px;
}

.nav-links a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--text);
  transition: width 0.3s ease;
}

.nav-links a:hover::after,
.nav-links a.active::after {
  width: 100%;
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 32px;
  height: 32px;
  cursor: pointer;
  z-index: 200;
  background: none;
  border: none;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 1.5px;
  background: var(--text);
  transition: all 0.3s ease;
  position: absolute;
}

.hamburger span:first-child {
  transform: translateY(-6px);
}

.hamburger span:last-child {
  transform: translateY(6px);
}

.hamburger.open span:first-child {
  transform: rotate(45deg);
}

.hamburger.open span:nth-child(2) {
  opacity: 0;
}

.hamburger.open span:last-child {
  transform: rotate(-45deg);
}

/* Mobile menu overlay */
.mobile-menu {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg);
  z-index: 150;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-menu.open {
  opacity: 1;
  pointer-events: auto;
}

.mobile-menu a {
  font-family: var(--serif);
  font-size: 2.5rem;
  font-weight: 500;
  margin: 16px 0;
  transition: opacity 0.3s ease;
}

.mobile-menu a:hover {
  opacity: 0.6;
}

/* ========================================
   Hero
   ======================================== */
.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 140px 48px 80px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.hero h1 {
  font-family: var(--serif);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 500;
  line-height: 1.1;
  letter-spacing: -0.03em;
  max-width: 900px;
}

/* ========================================
   Media Showcase (Triptych)
   ======================================== */
.media-showcase {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 16px;
  padding: 0 48px 120px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.media-block {
  aspect-ratio: 3 / 4;
  border-radius: 4px;
}

.media-block:nth-child(1) {
  background-color: var(--accent-terracotta);
}

.media-block:nth-child(2) {
  background-color: var(--accent-sage);
  transform: translateY(-40px);
}

.media-block:nth-child(3) {
  background-color: var(--accent-sand);
}

/* ========================================
   Client Marquee
   ======================================== */
.marquee-section {
  padding: 80px 0;
  overflow: hidden;
  border-top: 1px solid rgba(26, 26, 26, 0.08);
  border-bottom: 1px solid rgba(26, 26, 26, 0.08);
}

.marquee-row {
  display: flex;
  width: max-content;
  margin-bottom: 12px;
}

.marquee-row:last-child {
  margin-bottom: 0;
}

.marquee-track {
  display: flex;
  animation: marquee-scroll 30s linear infinite;
}

.marquee-row:nth-child(2) .marquee-track {
  animation-direction: reverse;
  animation-duration: 35s;
}

.marquee-row:nth-child(3) .marquee-track {
  animation-duration: 28s;
}

.marquee-item {
  font-family: var(--serif);
  font-size: clamp(1.5rem, 3vw, 2.5rem);
  font-weight: 500;
  white-space: nowrap;
  padding: 0 24px;
  color: var(--text);
  opacity: 0.85;
  display: flex;
  align-items: center;
  gap: 24px;
}

.marquee-item::after {
  content: '◦';
  font-size: 0.6em;
  opacity: 0.4;
}

@keyframes marquee-scroll {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(-50%);
  }
}

/* ========================================
   About Section
   ======================================== */
.about-section {
  padding: 120px 48px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.about-label {
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-light);
  margin-bottom: 32px;
}

.about-text {
  max-width: var(--reading-width);
  font-size: 1.125rem;
  line-height: 1.75;
  color: var(--text);
}

.about-text p {
  margin-bottom: 24px;
}

.about-text p:last-child {
  margin-bottom: 0;
}

/* ========================================
   Founder Letter (neweno.html)
   ======================================== */
.founder-section {
  min-height: 100vh;
  padding: 160px 48px 120px;
  max-width: var(--reading-width);
  margin: 0 auto;
}

.founder-greeting {
  font-family: var(--serif);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin-bottom: 48px;
}

.founder-body {
  font-size: 1.125rem;
  line-height: 1.85;
  color: var(--text);
}

.founder-body p {
  margin-bottom: 28px;
}

.founder-body p:last-child {
  margin-bottom: 0;
}

.founder-signature {
  margin-top: 64px;
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 600;
  font-style: italic;
}

/* ========================================
   Services Page
   ======================================== */
.philosophy-section {
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 160px 48px 80px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.philosophy-title {
  font-family: var(--serif);
  font-size: clamp(3rem, 8vw, 7rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.04em;
  margin-bottom: 48px;
}

.philosophy-text {
  max-width: var(--reading-width);
  font-size: 1.125rem;
  line-height: 1.75;
}

.philosophy-text p {
  margin-bottom: 24px;
}

.section-divider {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 48px;
}

.section-divider hr {
  border: none;
  border-top: 1px solid rgba(26, 26, 26, 0.12);
}

.services-section {
  padding: 80px 48px 120px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.services-heading {
  font-family: var(--serif);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 500;
  line-height: 1.3;
  margin-bottom: 64px;
  max-width: 600px;
}

.service-item {
  margin-bottom: 64px;
  max-width: var(--reading-width);
}

.service-item:last-child {
  margin-bottom: 0;
}

.service-name {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 600;
  margin-bottom: 16px;
}

.service-desc {
  font-size: 1.0625rem;
  line-height: 1.75;
  color: var(--text);
}

/* ========================================
   Clients Page
   ======================================== */
.clients-heading-section {
  padding: 160px 48px 40px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.clients-heading {
  font-family: var(--serif);
  font-size: clamp(3rem, 8vw, 7rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.04em;
}

.clients-subtitle {
  font-size: 1.125rem;
  color: var(--text-light);
  margin-top: 16px;
}

.clients-grid-section {
  padding: 64px 48px 120px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 48px 64px;
}

.client-card h3 {
  font-family: var(--serif);
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.client-card p {
  font-size: 0.9375rem;
  line-height: 1.65;
  color: var(--text-light);
}

/* ========================================
   Contact Page
   ======================================== */
.contact-hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 120px 48px;
}

.contact-heading {
  font-family: var(--serif);
  font-size: clamp(5rem, 18vw, 14rem);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: -0.05em;
  margin-bottom: 64px;
}

.contact-links {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
}

.contact-links a {
  font-family: var(--serif);
  font-size: 1.25rem;
  font-weight: 500;
  position: relative;
  padding-bottom: 2px;
}

.contact-links a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--text);
  transition: width 0.3s ease;
}

.contact-links a:hover::after {
  width: 100%;
}

/* ========================================
   Footer
   ======================================== */
.footer {
  padding: 48px;
  max-width: var(--max-width);
  margin: 0 auto;
  border-top: 1px solid rgba(26, 26, 26, 0.08);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
  color: var(--text-light);
}

.footer-links {
  display: flex;
  gap: 24px;
}

.footer-links a:hover {
  color: var(--text);
}

/* ========================================
   Responsive
   ======================================== */
@media (max-width: 1024px) {
  .media-showcase {
    gap: 12px;
  }

  .clients-grid {
    gap: 40px 48px;
  }
}

@media (max-width: 768px) {
  .nav {
    padding: 20px 24px;
  }

  .nav-links {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero {
    padding: 120px 24px 60px;
  }

  .hero h1 {
    font-size: clamp(2rem, 8vw, 3rem);
  }

  .media-showcase {
    grid-template-columns: 1fr;
    gap: 12px;
    padding: 0 24px 80px;
  }

  .media-block {
    aspect-ratio: 4 / 3;
  }

  .media-block:nth-child(2) {
    transform: none;
  }

  .about-section {
    padding: 80px 24px;
  }

  .founder-section {
    padding: 120px 24px 80px;
  }

  .philosophy-section {
    padding: 120px 24px 60px;
  }

  .section-divider {
    padding: 0 24px;
  }

  .services-section {
    padding: 60px 24px 80px;
  }

  .clients-heading-section {
    padding: 120px 24px 32px;
  }

  .clients-grid-section {
    padding: 48px 24px 80px;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .contact-hero {
    padding: 100px 24px;
  }

  .footer {
    padding: 32px 24px;
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .contact-heading {
    font-size: clamp(3.5rem, 20vw, 6rem);
  }

  .mobile-menu a {
    font-size: 2rem;
  }
}

