  font-weight: 500;
  position: relative;
  padding-bottom: 2px;
}

.contact-links a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--text);
  transition: width 0.3s ease;
}

.contact-links a:hover::after {
  width: 100%;
}

/* ========================================
   Footer
   ======================================== */
.footer {
  padding: 48px;
  max-width: var(--max-width);
  margin: 0 auto;
  border-top: 1px solid rgba(26, 26, 26, 0.08);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
  color: var(--text-light);
}

.footer-links {
  display: flex;
  gap: 24px;
}

.footer-links a:hover {
  color: var(--text);
}

/* ========================================
   Responsive
   ======================================== */
@media (max-width: 1024px) {
  .media-showcase {
    gap: 12px;
  }

  .clients-grid {
    gap: 40px 48px;
  }
}

@media (max-width: 768px) {
  .nav {
    padding: 20px 24px;
  }

  .nav-links {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero {
    padding: 120px 24px 60px;
  }

  .hero h1 {
    font-size: clamp(2rem, 8vw, 3rem);
  }

  .media-showcase {
    grid-template-columns: 1fr;
    gap: 12px;
    padding: 0 24px 80px;
  }

  .media-block {
    aspect-ratio: 4 / 3;
  }

  .media-block:nth-child(2) {
    transform: none;
  }

  .about-section {
    padding: 80px 24px;
  }

  .founder-section {
    padding: 120px 24px 80px;
  }

  .philosophy-section {
    padding: 120px 24px 60px;
  }

  .section-divider {
    padding: 0 24px;
  }

  .services-section {
    padding: 60px 24px 80px;
  }

  .clients-heading-section {
    padding: 120px 24px 32px;
  }

  .clients-grid-section {
    padding: 48px 24px 80px;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .contact-hero {
    padding: 100px 24px;
  }

  .footer {
    padding: 32px 24px;
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .contact-heading {
    font-size: clamp(3.5rem, 20vw, 6rem);
  }

  .mobile-menu a {
    font-size: 2rem;
  }
}
